window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[310]={"id":"310","numero":310,"titre":"Tumeurs de la prostate","objectifs":[{"id":"310-1","rang":"B","rubrique":"Définition","titre":"Connaître les principales lésions bénignes et malignes de la prostate","contenu":"<p>La prostate héberge deux grandes catégories de lésions à connaître : la <strong><span class=\"kw-def\">lésion bénigne</span></strong> dominante (<strong><span class=\"kw-def\">hypertrophie bénigne de la prostate (HBP)</span></strong>) et la <strong><span class=\"kw-def\">lésion maligne</span></strong> dominante (<strong><span class=\"kw-def\">adénocarcinome</span></strong>, plus de <span class=\"kw-chiffre\">95 %</span> des cancers). Le piège pédagogique majeur est topographique et fonctionnel : <strong>HBP et cancer ne siègent pas dans la même zone et n'évoluent pas l'un vers l'autre</strong>.</p>\n      <table >\n        <thead>\n          <tr><th></th><th>HBP (<span class=\"kw-clinique\">lésion</span> bénigne)</th><th>Cancer (lésion maligne)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Localisation</td>\n            <td><strong><span class=\"kw-def\">Zone de transition</span></strong> (périurétrale)</td>\n            <td><strong><span class=\"kw-def\">Zone périphérique</span></strong> dans la grande majorité des cas</td>\n          </tr>\n          <tr>\n            <td>Sémiologie au TR</td>\n            <td><strong>Glande <span class=\"kw-clinique\">souple</span>, <span class=\"kw-clinique\">lisse</span>, <span class=\"kw-clinique\">indolore</span>, régulière</strong> ; sillon médian effacé si volume <span class=\"kw-chiffre\">&gt; 20 g</span></td>\n            <td><strong><span class=\"kw-clinique\">Nodule</span> <span class=\"kw-clinique\">dur/pierreux</span>, <span class=\"kw-clinique\">irrégulier</span>, <span class=\"kw-clinique\">non douloureux</span></strong> ; blindage pelvien si extension</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">Histologie</span> / Phénotype</td>\n            <td>Hyperplasie nodulaire bénigne du stroma et de l'épithélium glandulaire</td>\n            <td><strong>Adénocarcinome luminal</strong> <span class=\"kw-bio\">p63−</span> / <span class=\"kw-bio\">PSA+</span> dans <span class=\"kw-chiffre\">&gt; 95 %</span></td>\n          </tr>\n          <tr>\n            <td>Hormono-sensibilité</td>\n            <td>Sensible aux androgènes (justifie inhibiteurs <span class=\"kw-ttt\">5α-réductase</span> et α-bloquants)</td>\n            <td>Hormonosensible (sensible à la <strong><span class=\"kw-ttt\">castration androgénique</span></strong>) à la phase initiale</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Évolution</span> maligne</td>\n            <td colspan=\"2\"><strong><span class=\"kw-alerte\">L'HBP ne dégénère JAMAIS en cancer de la prostate ❌</span></strong> — pas de filiation lésionnelle entre <span class=\"kw-clinique\">les</span> deux</td>\n          </tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Autres tumeurs malignes (rares)</h4>\n      <table >\n        <thead>\n          <tr><th>Entité</th><th>Fréquence</th><th>Points clés</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Carcinome neuroendocrine</span></strong> (cancer à petites cellules)</td>\n            <td><span class=\"kw-chiffre\">&lt; 5 %</span></td>\n            <td>Très rare ; <span class=\"kw-alerte\">agressif</span> ; non sensible à la castration</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Lymphome</span>, <span class=\"kw-def\">sarcome</span>, métastases</td>\n            <td>Exceptionnel</td>\n            <td>À évoquer en cas de tableau atypique (<span class=\"kw-bio\">PSA</span> non concordant, <span class=\"kw-clinique\">masse</span> rapide)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique :</strong> <span class=\"kw-ci\">ne jamais</span> raisonner « HBP qui dégénère » — l'HBP siège en zone de <span class=\"kw-def\">transition</span>, le cancer en zone <span class=\"kw-def\">périphérique</span>. <span class=\"kw-clinique\">Les</span> deux peuvent coexister chez le même patient sans lien évolutif.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 127 — Hypertrophie de prostate bénigne · 311 — Tumeur rénale · 313 — Tumeur testicule · 314 — Tumeur vésicale</em></p>","frequence":2},{"id":"310-2","rang":"B","rubrique":"Épidémiologie","titre":"Connaître l’épidémiologie du cancer de la prostate","contenu":"<p>Le cancer de la prostate est <strong>le cancer le plus fréquent chez l'homme</strong> de plus de <span class=\"kw-chiffre\">50 ans</span> en France. Son profil épidémiologique combine une <span class=\"kw-def\">incidence</span> très élevée et une mortalité relativement modérée (cancer fréquent mais de <strong>cinétique lente</strong>) — ce qui explique l'absence de <span class=\"kw-def\">dépistage</span> organisé en population générale.</p>\n      <table >\n        <thead>\n          <tr><th></th><th>Données clés</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Incidence</span></td>\n            <td>\n              <strong><span class=\"kw-def\">Incidence</span> :</strong> <span class=\"kw-chiffre\">50 400</span> nouveaux cas/an ; <span class=\"kw-chiffre\">25 %</span> des cancers masculins (rang 1)<br>\n              <strong>Surrisque géographique :</strong> incidence <span class=\"kw-chiffre\">× 2</span> dans <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">Antilles françaises</span> (pollution <span class=\"kw-etio\">chlordécone</span>)<br>\n              <strong><span class=\"kw-clinique\">Évolution</span> temporelle :</strong> forte hausse depuis 1980 (vieillissement + dosage <span class=\"kw-bio\">PSA</span>) ; baisse nette en 2011 (démarche diagnostique plus raisonnée) ; incidence <strong>actuellement stable</strong>\n            </td>\n          </tr>\n          <tr>\n            <td>Âge</td>\n            <td>\n              <strong>Âge moyen au diagnostic :</strong> <span class=\"kw-chiffre\">68 ans</span><br>\n              <strong>Âge médian de décès :</strong> <span class=\"kw-chiffre\">83 ans</span> (la majorité des patients diagnostiqués décèdent d'une autre cause)\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Mortalité</span></td>\n            <td>\n              <strong>Rang :</strong> <span class=\"kw-alerte\">3<sup>e</sup> cause de décès par cancer chez l'homme</span><br>\n              <strong>Chiffres :</strong> <span class=\"kw-chiffre\">8 100</span> à <span class=\"kw-chiffre\">10 000</span> décès/an<br>\n              <strong>Tendance :</strong> en <strong>baisse depuis 1990</strong> (détection précoce ouvrant la fenêtre de curabilité + amélioration des traitements de la phase métastatique résistante à la castration)\n            </td>\n          </tr>\n          <tr>\n            <td>Survie</td>\n            <td>\n              <strong>Survie à<span class=\"kw-chiffre\"> 5 ans</span> :</strong> <span class=\"kw-chiffre\">93 %</span><br>\n              <strong>Survie à<span class=\"kw-chiffre\"> 10 ans</span> :</strong> <span class=\"kw-chiffre\">80 %</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Cancer <strong>fréquent</strong> mais à <strong><span class=\"kw-clinique\">évolution</span> lente</strong> : c'est l'argument central qui justifie l'absence de <strong><span class=\"kw-alerte\">dépistage de masse organisé</span></strong> et qui oriente vers un <strong><span class=\"kw-def\">dépistage</span> individuel ciblé</strong> chez l'homme entre <span class=\"kw-chiffre\">50</span> et <span class=\"kw-chiffre\">70 ans</span> à espérance de vie <span class=\"kw-chiffre\">&gt; 10 ans</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 290 — Epidémiologie cancers</em></p>","frequence":1},{"id":"310-3","rang":"A","rubrique":"Étiologie","titre":"Connaître les principaux facteurs de risque du cancer de la prostate","contenu":"<p>Quatre familles de <strong><span class=\"kw-def\">facteurs de risque</span> (FR)</strong> dominent l'item : <strong>âge</strong>, <strong>origine ethnique</strong>, <strong><span class=\"kw-def\">terrain</span> <span class=\"kw-etio\">génétique</span></strong>, et <strong>facteurs environnementaux / métaboliques</strong>. À l'inverse, plusieurs distracteurs reviennent en QCM (<span class=\"kw-etio\">alcool</span>, tabac, faible fréquence éjaculatoire) — ils ne sont <strong>pas</strong> retenus comme FR.</p>\n      <table >\n        <thead>\n          <tr><th>Famille</th><th>Détails à connaître</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Âge</strong></td>\n            <td>\n              <strong>FR majeur ;</strong> diagnostic exceptionnel avant <span class=\"kw-chiffre\">50 ans</span> (sauf autres FR)<br>\n              <strong>Pic d'<span class=\"kw-def\">incidence</span> :</strong> <span class=\"kw-chiffre\">68 ans</span> ; décroissance au-delà\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Origine ethnique</strong></td>\n            <td>\n              <strong>Hiérarchie :</strong> <span class=\"kw-etio\">homme à peau noire</span> &gt; caucasien &gt; asiatique<br>\n              <strong>Surrisque :</strong> ascendants d'<span class=\"kw-etio\">Afrique noire</span> ; <strong>population antillaise = une des populations <span class=\"kw-clinique\">les</span> plus à risque au monde</strong> (<span class=\"kw-def\">incidence</span> et mortalité plus élevées, agressivité accrue, plus de récidives après traitement curatif)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Facteurs génétiques</strong></td>\n            <td>\n              <strong>FR le plus documenté</strong> ; <span class=\"kw-chiffre\">95 %</span> polygénique ; <span class=\"kw-chiffre\">5 %</span> monogénique<br>\n              <strong>Mutations constitutionnelles :</strong> <span class=\"kw-bio\">BRCA2</span> ++ ; <span class=\"kw-bio\">BRCA1</span> ; <span class=\"kw-bio\">HOXB13</span> ; <span class=\"kw-bio\">ATM</span><br>\n              <strong>Formes héréditaires :</strong> âge de survenue précoce + agressivité accrue\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hormonaux / Alimentaires / Environnementaux</strong></td>\n            <td>\n              <strong>Syndrome métabolique</strong> et <strong><span class=\"kw-etio\">obésité</span></strong> : risque accru de cancer à <span class=\"kw-alerte\">haut risque</span> (et risque diminué pour <span class=\"kw-clinique\">les</span> formes à faible risque)<br>\n              <strong>Perturbateurs endocriniens :</strong> <span class=\"kw-etio\">chlordécone</span> (insecticide utilisé aux Antilles, <strong>reconnu maladie professionnelle en <span class=\"kw-chiffre\">2021</span></strong>)<br>\n              <strong>Facteurs hormonaux :</strong> cancer observé uniquement chez l'homme pubère et hormono-sensible (sans preuve formelle d'un rôle dans la carcinogenèse)<br>\n              <strong>Alimentation :</strong> <span class=\"kw-etio\">alimentation riche en graisses animales</span> (signal faible, non spécifique)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>NON-FR (distracteurs QCM)</strong></td>\n            <td>\n              <span class=\"kw-ci\">Tabac ❌</span> ; <span class=\"kw-ci\">alcool ❌</span> ; <span class=\"kw-ci\">traitement androgénique ❌</span> ; <span class=\"kw-ci\">faible fréquence éjaculatoire ❌</span> ; <span class=\"kw-ci\">régime alimentaire spécifique ❌</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Piège classique QCM.</strong> Le <span class=\"kw-ci\">tabac n'est PAS un facteur de risque du cancer de la prostate ❌</span> — distracteur récurrent à éliminer d'emblée.</div>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Indications de consultation oncogénétique</h4>\n      <table >\n        <thead>\n          <tr><th>Situation</th><th>Critère</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Patient jeune</td>\n            <td>Tumeur de la prostate diagnostiquée <strong>avant <span class=\"kw-chiffre\">50 ans</span></strong></td>\n          </tr>\n          <tr>\n            <td>Forme familiale prostate</td>\n            <td>\n              <strong>3 cancers</strong> de la prostate quel que soit l'âge dans la même branche familiale (1<sup>er</sup>/2<sup>nd</sup> degré) OU<br>\n              <strong>2 cancers</strong> de la prostate diagnostiqués <strong>&lt; <span class=\"kw-chiffre\">55 ans</span></strong> dans la même branche familiale\n            </td>\n          </tr>\n          <tr>\n            <td>Histoire familiale BRCA</td>\n            <td>\n              <strong>Cancer de l'ovaire :</strong> <span class=\"kw-chiffre\">1 seul cas</span> suffit<br>\n              <strong>Cancer du sein :</strong> diagnostiqué <strong>&lt; <span class=\"kw-chiffre\">40 ans</span></strong> OU <strong>bilatéral</strong> OU chez un <strong>homme</strong>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Dépistage</span> individuel précoce</h4>\n      <table >\n        <thead>\n          <tr><th></th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Population cible</td>\n            <td>Homme avec survie estimée <span class=\"kw-chiffre\">&gt; 10 ans</span>, entre <span class=\"kw-chiffre\">50</span> et <span class=\"kw-chiffre\">70 ans</span>, ou dès <span class=\"kw-chiffre\">40 ans</span> en présence de FR (notamment <span class=\"kw-bio\">BRCA2</span> / <span class=\"kw-bio\">HOXB13</span>)</td>\n          </tr>\n          <tr>\n            <td>Outils</td>\n            <td><strong><span class=\"kw-clinique\">Toucher rectal (TR)</span> + dosage <span class=\"kw-bio\">PSA total</span></strong></td>\n          </tr>\n          <tr>\n            <td>Rythme</td>\n            <td>Tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 à 4 ans</span> ; espacement possible si <span class=\"kw-bio\">PSA</span> <span class=\"kw-chiffre\">&lt; 1 ng/mL</span> à<span class=\"kw-chiffre\"> 45 ans</span> ou <span class=\"kw-chiffre\">60 ans</span></td>\n          </tr>\n          <tr>\n            <td>NON ❌</td>\n            <td><span class=\"kw-ci\">Pas de dépistage de masse organisé ❌</span> ; <span class=\"kw-ci\">aucune modalité de chimioprévention recommandée ❌</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 290 — Epidémiologie cancers · 291 — Cancérogénèse - oncogénétique</em></p>","frequence":0},{"id":"310-4","rang":"B","rubrique":"Physiopathologie","titre":"Connaître le mode d’extension du cancer de la prostate","contenu":"<p>Le cancer de la prostate se développe d'abord localement au sein de la glande (tumeur isolée ou plus diffuse), puis évolue selon <strong>trois voies d'extension</strong> à connaître pour le <span class=\"kw-def\">bilan d'extension</span> : <strong>locale (capsule → voisinage)</strong>, <strong>lymphatique (ganglions pelviens)</strong> et <strong>hématogène (os ++ et viscères)</strong>.</p>\n      <table >\n        <thead>\n          <tr><th>Voie d'extension</th><th>Sites concernés</th><th>Conséquences cliniques</th><th><span class=\"kw-def\">Pronostic</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Extension locale</strong></td>\n            <td>\n              <strong>Capsule prostatique :</strong> franchissement = <span class=\"kw-chiffre\">T3a</span><br>\n              <strong>Vésicules séminales :</strong> <span class=\"kw-bio\">envahissement</span> = <span class=\"kw-chiffre\">T3b</span><br>\n              <strong>Col vésical / abouchement des uretères :</strong> envahissement<br>\n              <strong>Urètre prostatique</strong><br>\n              <strong>Rectum :</strong> plus rarement (<span class=\"kw-chiffre\">T4</span>)\n            </td>\n            <td>\n              <strong>Col / uretères :</strong> <span class=\"kw-clinique\">urétéro-hydronéphrose</span> uni- ou bilatérale<br>\n              <strong>Urètre :</strong> <span class=\"kw-clinique\">obstruction vésicale</span><br>\n              <strong>Rectum :</strong> blindage pelvien\n            </td>\n            <td>Éléments pronostiques majeurs (<span class=\"kw-chiffre\">T3a</span>, <span class=\"kw-chiffre\">T3b</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Diffusion lymphatique</strong></td>\n            <td>\n              <strong>Premier relais :</strong> ganglions <strong>ilio-obturateurs</strong><br>\n              <strong>Puis :</strong> iliaque interne → le long de la <strong>VCI</strong> jusqu'en sous-rénal\n            </td>\n            <td>\n              <span class=\"kw-clinique\">Adénopathies</span> <strong>non palpables</strong> en règle générale<br>\n              <span class=\"kw-clinique\">Œdèmes des membres inférieurs</span> (surtout <strong>asymétriques</strong>) si compression veineuse pelvienne\n            </td>\n            <td>N1 = haut risque ; oriente le bilan vers <span class=\"kw-imagerie\">TDM</span> TAP + <span class=\"kw-imagerie\">TEP</span>-PSMA</td>\n          </tr>\n          <tr>\n            <td><strong>Diffusion hématogène</strong></td>\n            <td>\n              <strong>Métastases osseuses ++</strong> (essentiel de la <span class=\"kw-def\">morbidité</span>)<br>\n              <strong>Métastases viscérales :</strong> foie, poumons\n            </td>\n            <td>\n              <strong>Os :</strong> <span class=\"kw-clinique\">douleurs osseuses inflammatoires nocturnes</span>, <span class=\"kw-clinique\">anémie par envahissement médullaire</span>, <span class=\"kw-alerte\">compression médullaire</span> (métastases rachidiennes ⇒ <span class=\"kw-alerte\">urgence</span> neurologique)<br>\n              <strong>Viscères :</strong> <span class=\"kw-alerte\">mauvais pronostic</span>\n            </td>\n            <td>Os majoritaire ; viscérales = <span class=\"kw-alerte\">facteur de mauvais pronostic</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Discriminant QCM (très tombable).</strong> <span class=\"kw-clinique\">Les</span> métastases osseuses du cancer de la prostate sont majoritairement <strong><span class=\"kw-imagerie\">ostéo-condensantes</span></strong> (et biologiquement <strong>mixtes</strong>, avec excès de résorption ET de fabrication osseuse). C'est <strong>LA</strong> spécificité du cancer de la prostate <span class=\"kw-bio\">vs</span> les autres cancers (poumon, sein, rein) où les métastases sont majoritairement <em>ostéolytiques</em>.</div>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> neurologique à reconnaître.</strong> <span class=\"kw-alerte\">Compression médullaire</span> sur métastase rachidienne = <strong>urgence diagnostique et thérapeutique</strong> (paresthésies, déficit moteur, <span class=\"kw-clinique\">syndrome de la</span> queue de cheval). <span class=\"kw-imagerie\">IRM</span> rachidienne en urgence + <span class=\"kw-ttt\">corticothérapie</span> + avis neurochirurgical/<span class=\"kw-ttt\">radiothérapie</span> en urgence.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 91 — Déficit neuro récent · 257 — Oedèmes des membres inférieurs · 348 — <span class=\"kw-ci\">Insuffisance rénale</span> aiguë - anurie</em></p>","frequence":1},{"id":"310-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les grandes présentations cliniques du cancer de la prostate","contenu":"<p><strong>Le pattern dominant est l'<span class=\"kw-clinique\">asymptomatique</span></strong> : la majorité des patients sont diagnostiqués via un <span class=\"kw-def\">dépistage</span> individuel (TR + <span class=\"kw-bio\">PSA</span>), car le cancer évolue lentement. L'examen clinique est <strong>le plus souvent normal</strong>. Trois grandes présentations cliniques à connaître : (1) <strong>découverte au TR</strong> (<span class=\"kw-clinique\">nodule</span> suspect), (2) <strong>symptômes urinaires</strong> (souvent liés à une HBP associée, plus rarement à un <span class=\"kw-bio\">envahissement</span> par le cancer), (3) <strong>atteintes secondaires</strong> révélatrices (<span class=\"kw-chiffre\">10 %</span> au diagnostic).</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Toucher rectal — Cancer <span class=\"kw-bio\">vs</span> HBP</h4>\n      <table >\n        <thead>\n          <tr><th></th><th>Cancer de la prostate</th><th>HBP</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Aspect au TR</td>\n            <td><strong><span class=\"kw-clinique\">Nodule</span> <span class=\"kw-clinique\">dur/pierreux</span>, <span class=\"kw-clinique\">irrégulier</span>, <span class=\"kw-clinique\">non douloureux</span></strong> ; limité à <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span> l</span>obe ou plus diffus ; <strong><span class=\"kw-def\">blindage pelvien</span></strong> si extension aux organes de voisinage</td>\n            <td><strong>Glande <span class=\"kw-clinique\">souple</span>, <span class=\"kw-clinique\">lisse</span>, <span class=\"kw-clinique\">indolore</span>, régulière</strong> ; volume <span class=\"kw-chiffre\">&gt; 20 g</span> avec <span class=\"kw-clinique\">disparition du sillon médian</span> et <span class=\"kw-clinique\">évasement des bords latéraux</span></td>\n          </tr>\n          <tr>\n            <td>Conduite à tenir</td>\n            <td><strong>Toute anomalie au TR évoquant un cancer ⇒ <span class=\"kw-alerte\">biopsies prostatiques écho-guidées QUEL QUE SOIT le PSA</span></strong></td>\n            <td>TR signe le <span class=\"kw-def\">diagnostic positif</span> d'HBP, sans permettre d'imputer formellement <span class=\"kw-clinique\">les</span> SBAU à l'HBP</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Piège classique.</strong> <span class=\"kw-alerte\">Un TR normal n'élimine PAS un cancer de la prostate ❌</span>. Inversement, toute anomalie au TR doit faire poser l'indication de biopsies écho-guidées <strong>indépendamment du taux de <span class=\"kw-bio\">PSA</span></strong>.</div>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Autres présentations cliniques</h4>\n      <table >\n        <thead>\n          <tr><th>Présentation</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Symptômes urinaires</strong></td>\n            <td>\n              <strong>Manifestations :</strong> <span class=\"kw-clinique\">SBAU</span> (signes du bas appareil urinaire), <span class=\"kw-clinique\">hématurie</span>, <span class=\"kw-clinique\">RAU</span> (rétention aiguë d'urine)<br>\n              <strong>Mécanisme :</strong> le plus souvent <strong>HBP associée</strong> (++) ; <strong>exceptionnellement</strong> <span class=\"kw-bio\">envahissement</span> trigonal ou urètre prostatique par le cancer<br>\n              <strong>Discriminant :</strong> le <span class=\"kw-clinique\">TR</span> fait la différence\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Symptômes sexuels</strong></td>\n            <td>\n              <strong>Cancer en lui-même :</strong> n'entraîne <span class=\"kw-ci\">pas de symptômes sexuels ❌</span> (un épisode isolé d'hémospermie n'est pas un signe d'appel)<br>\n              <strong>Conséquences iatrogènes :</strong> <span class=\"kw-clinique\">hémospermie</span> après biopsies ; <span class=\"kw-clinique\">dysfonction érectile</span> et <span class=\"kw-clinique\">atrophie des OGE</span> après certains traitements (<span class=\"kw-imagerie\">RT</span>, hormonothérapie)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Atteintes secondaires</strong> (<span class=\"kw-chiffre\">10 %</span> au diagnostic)</td>\n            <td>\n              <strong><span class=\"kw-clinique\">AEG</span> / anémie :</strong> <span class=\"kw-clinique\">altération de l'état général</span> et <span class=\"kw-clinique\">anémie</span> par <span class=\"kw-bio\">envahissement</span> médullaire métastatique<br>\n              <strong>Anurie :</strong> <span class=\"kw-alerte\">insuffisance rénale aiguë obstructive</span> par envahissement des uretères<br>\n              <strong>Douleurs osseuses :</strong> <span class=\"kw-clinique\">douleurs osseuses inflammatoires à prédominance nocturne</span> = métastases osseuses<br>\n              <strong>Signes neurologiques :</strong> paresthésies, déficit musculaire, voire <span class=\"kw-alerte\">syndrome de la queue de cheval</span> = <span class=\"kw-alerte\">compression médullaire</span> par métastases rachidiennes<br>\n              <strong><span class=\"kw-clinique\">Adénopathies</span> :</strong> non palpables en général (ilio-obturatrices → iliaque interne → VCI sous-rénal)<br>\n              <strong><span class=\"kw-clinique\">Œdèmes</span> :</strong> <span class=\"kw-clinique\">œdèmes des membres inférieurs asymétriques</span> = signe indirect d'extension ganglionnaire pelvienne avec compression veineuse\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Outils standardisés d'évaluation de base</h4>\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-def\">Score</span></th><th>Domaine évalué</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">USP</span></strong> (Urinary Symptom Profile)</td>\n            <td>Fonction urinaire</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">IIEF</span></strong> (International Index of Erectile Function)</td>\n            <td>Fonction sexuelle</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À mémoriser pour le QCM.</strong> Sémio TR <strong>cancer prostate</strong> = <strong><span class=\"kw-clinique\">nodule</span> DUR/PIERREUX/IRRÉGULIER/NON DOULOUREUX</strong> (« pierre dans un sac de coton »). Sémio TR <strong>HBP</strong> = glande <strong>SOUPLE/LISSE/INDOLORE/RÉGULIÈRE</strong>, sillon disparu. Cette opposition tombe systématiquement.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 125 — Trouble miction - incontinence urinaire · 127 — Hypertrophie de prostate bénigne · 91 — Déficit neuro récent · 348 — <span class=\"kw-ci\">Insuffisance rénale</span> aiguë - anurie</em></p>","frequence":3},{"id":"310-6","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens paracliniques de première intention devant une suspicion de cancer de la prostate (règles de bon usage du dosage de l’antigène prostatique spécifique (PSA))","contenu":"<p><strong>Objectif majeur de l'item</strong> (14 ⭐ QCM EDN). Trois axes : (1) <strong>règles de bon usage du <span class=\"kw-bio\">PSA</span></strong>, (2) <strong>arbre décisionnel</strong> devant un TR / <span class=\"kw-bio\">PSA</span> suspect, (3) <strong>biopsies prostatiques écho-guidées + imagerie + <span class=\"kw-bio\">histologie</span></strong> (ISUP, Gleason, <span class=\"kw-def\">classification</span> d'Amico) et <span class=\"kw-def\">bilan d'extension</span> par classe d'Amico.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">1) <span class=\"kw-bio\">PSA</span> total — règles de bon usage</h4>\n      <table >\n        <thead>\n          <tr><th></th><th>Données clés</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Définition</td>\n            <td><strong><span class=\"kw-bio\">Prostate Specific Antigen</span></strong> — glycoprotéine de la famille des <strong>kallikréines</strong>, rôle dans la liquéfaction du sperme ; <strong>spécifique de l'épithélium prostatique</strong> (sain ou <span class=\"kw-etio\">tumoral</span>), <strong>pas spécifique du cancer</strong></td>\n          </tr>\n          <tr>\n            <td>Valeurs</td>\n            <td>\n              <strong>Valeur normale :</strong> <span class=\"kw-chiffre\">&lt; 4 ng/mL</span> (augmente avec l'âge)<br>\n              <strong>Seuil d'<span class=\"kw-clinique\">évolution</span> métastatique suspectée :</strong> <span class=\"kw-chiffre\">&gt; 15-20 ng/mL</span> ⇒ justifie un <span class=\"kw-def\">bilan d'extension</span>\n            </td>\n          </tr>\n          <tr>\n            <td>Variations</td>\n            <td>\n              <strong>↑ <span class=\"kw-bio\">PSA</span> :</strong> cancer de la prostate, <strong><span class=\"kw-def\">HBP</span></strong>, <strong><span class=\"kw-def\">prostatite</span> aiguë</strong>, <strong><span class=\"kw-clinique\">RAU</span></strong>, manipulations prostatiques (<span class=\"kw-clinique\">TR</span>, sondage)<br>\n              <strong>↓ <span class=\"kw-bio\">PSA</span> :</strong> inhibiteurs de la <strong><span class=\"kw-ttt\">5α-réductase</span></strong> (jusqu'à <span class=\"kw-chiffre\">−50 %</span>) ; traitements anticancéreux (<span class=\"kw-bio\">PSA</span> <span class=\"kw-chiffre\">&lt; 0,2 ng/mL</span> ou indosable après prostatectomie totale)\n            </td>\n          </tr>\n          <tr>\n            <td>Conduite à tenir</td>\n            <td>\n              <strong>Confirmation :</strong> <span class=\"kw-alerte\">toujours confirmer un PSA élevé par un 2<sup>e</sup> dosage à <span class=\"kw-chiffre\">1 mois</span></span> avant d'adresser le patient en urologie (variabilité intra-individuelle <span class=\"kw-chiffre\">20-30 %</span>)<br>\n              <strong>Éviter le dosage :</strong> en cas d'événement perturbateur récent (<span class=\"kw-clinique\">infection urinaire</span> masculine peut maintenir <span class=\"kw-bio\">PSA</span> élevé plusieurs mois) ; répéter à distance\n            </td>\n          </tr>\n          <tr>\n            <td>Utilités</td>\n            <td>\n              <strong>Diagnostic :</strong> intérêt controversé pour le <span class=\"kw-def\">dépistage</span> isolé, <span class=\"kw-ci\">non fiable pour poser le diagnostic ❌</span><br>\n              <strong><span class=\"kw-def\">Pronostic</span> / <span class=\"kw-def\">stadification</span> :</strong> utile (intégré dans Amico)<br>\n              <strong><span class=\"kw-def\">Suivi</span> :</strong> très utile (post-prostatectomie, post-<span class=\"kw-imagerie\">RT</span>, hormonothérapie, traitements systémiques)\n            </td>\n          </tr>\n          <tr>\n            <td>Densité du <span class=\"kw-bio\">PSA</span></td>\n            <td>\n              <strong>Rationnel :</strong> le volume prostatique influence le taux de <span class=\"kw-bio\">PSA</span> (↑ normale avec le volume)<br>\n              <strong>Seuil :</strong> rapport <strong><span class=\"kw-bio\">PSA</span> / volume prostatique &gt; <span class=\"kw-chiffre\">0,15</span></strong> = argument supplémentaire pour des biopsies prostatiques<br>\n              <strong>Exemple :</strong> <span class=\"kw-bio\">PSA</span> à<span class=\"kw-chiffre\"> 5 ng/mL</span> est « normal » chez un patient avec prostate de <span class=\"kw-chiffre\">50 mL</span> (densité 0,10)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Règle de bon usage cardinale.</strong> <span class=\"kw-alerte\">Tout PSA élevé doit être confirmé par un 2<sup>e</sup> dosage à 1 mois</span> (variabilité<span class=\"kw-chiffre\"> 20-30 %</span>) <strong>avant</strong> l'adressage en urologie. Éviter de doser en période de TR récent, sondage, RAU, <span class=\"kw-clinique\">prostatite</span> ou infection urinaire en cours.</div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">2) Arbre décisionnel devant une suspicion (TR + <span class=\"kw-bio\">PSA</span>)</h4>\n      <table >\n        <thead>\n          <tr><th>Étape</th><th>Action</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>1. Patient à risque ou demandeur</td>\n            <td>Information → décision partagée pour engager la démarche diagnostique</td>\n          </tr>\n          <tr>\n            <td>2. <span class=\"kw-clinique\">TR</span> + dosage du <span class=\"kw-bio\">PSA</span></td>\n            <td>\n              <strong>TR suspect :</strong> consultation urologie d'emblée<br>\n              <strong>TR normal :</strong> apprécier la <strong>densité du <span class=\"kw-bio\">PSA</span></strong> (option : <span class=\"kw-imagerie\">échographie</span> endorectale si évaluation volumique difficile)\n            </td>\n          </tr>\n          <tr>\n            <td>3. Évaluation densité <span class=\"kw-bio\">PSA</span></td>\n            <td>\n              <strong>Rassurante :</strong> <span class=\"kw-def\">réévaluation</span> à intervalle régulier<br>\n              <strong>Inquiétante :</strong> nouveau dosage à <span class=\"kw-chiffre\">≥ 1 mois</span> d'intervalle\n            </td>\n          </tr>\n          <tr>\n            <td>4. Nouveau dosage <span class=\"kw-bio\">PSA</span></td>\n            <td>\n              <strong>Toujours inquiétant :</strong> consultation urologie<br>\n              <strong>Devenu rassurant :</strong> <span class=\"kw-def\">réévaluation</span> à intervalle régulier\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Piège majeur.</strong> <span class=\"kw-alerte\">L'<span class=\"kw-imagerie\">IRM prostatique</span> n'est PAS recommandée à ce stade de prise en charge ❌</span> (avant la décision de <span class=\"kw-ttt\">biopsie</span>). Son indication vient APRÈS la décision de biopsie, dans la préparation du geste.</div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">3) Biopsies prostatiques écho-guidées</h4>\n      <table >\n        <thead>\n          <tr><th></th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Indications</td>\n            <td>TR suspect (quel que soit le <span class=\"kw-bio\">PSA</span>) OU <span class=\"kw-bio\">PSA</span> élevé confirmé à <span class=\"kw-chiffre\">1 mois</span></td>\n          </tr>\n          <tr>\n            <td>Objectifs</td>\n            <td><span class=\"kw-def\">Diagnostic positif</span> ; agressivité (<span class=\"kw-bio\">ISUP</span> / <span class=\"kw-bio\">Gleason</span>) ; extension <span class=\"kw-etio\">tumorale</span> (selon le nombre de biopsies positives)</td>\n          </tr>\n          <tr>\n            <td>Préparation</td>\n            <td>\n              <strong><span class=\"kw-imagerie\">IRM</span> mp préalable</strong> si possible (avant <span class=\"kw-clinique\">les</span> biopsies)<br>\n              <strong>Évaluation <span class=\"kw-etio\">hémorragique</span> :</strong> arrêt/relais des antithrombotiques<br>\n              <strong>Lavement rectal</strong><br>\n              <strong><span class=\"kw-ttt\">Antibioprophylaxie</span> systématique :</strong> <span class=\"kw-ttt\">fluoroquinolone systémique</span> PO en prise unique <span class=\"kw-chiffre\">1-2 h</span> avant ; <span class=\"kw-ttt\">ceftriaxone</span> en alternative (<span class=\"kw-ci\">allergie</span> / prise de quinolone &lt;<span class=\"kw-chiffre\"> 6 mois</span>)\n            </td>\n          </tr>\n          <tr>\n            <td>Modalités</td>\n            <td>\n              <strong>Anesthésie :</strong> locale (bloc périprostatique à la <span class=\"kw-ttt\">lidocaïne</span>) ; possible au bloc sous ALR/AG<br>\n              <strong>Voies d'abord :</strong> transrectale ou transpérinéale<br>\n              <strong>Guidage :</strong> <span class=\"kw-imagerie\">échographie</span> endorectale<br>\n              <strong>Prélèvements :</strong> <span class=\"kw-chiffre\">12 carottes</span> standard (2 base + 2 partie moyenne + 2 apex × <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> l</span>obes) + <strong>biopsies ciblées</strong> supplémentaires si zone <span class=\"kw-imagerie\">PI-RADS ≥ 3</span> sur <span class=\"kw-imagerie\">IRM</span> préalable\n            </td>\n          </tr>\n          <tr>\n            <td>FR de complications</td>\n            <td>ATCD d'<span class=\"kw-ci\">allergie</span> (latex, <span class=\"kw-ttt\">lidocaïne</span>, ATB) ; troubles de la coagulation ; ATCD de <span class=\"kw-clinique\">prostatite</span> ; prise d'ATB &lt;<span class=\"kw-chiffre\"> 6 mois</span> ; <span class=\"kw-alerte\">hospitalisation</span> &lt;<span class=\"kw-chiffre\"> 3 mois</span> ; vie en institution ; sonde urinaire</td>\n          </tr>\n          <tr>\n            <td>Risques spécifiques</td>\n            <td>\n              <strong>Précoces :</strong> <span class=\"kw-clinique\">douleur pelvienne</span> ; <span class=\"kw-clinique\">rectorragies</span> ; <span class=\"kw-clinique\">hématurie</span> (<span class=\"kw-alerte\">hospitalisation</span> &lt;<span class=\"kw-chiffre\"> 1 %</span>)<br>\n              <strong>Persistant :</strong> <span class=\"kw-clinique\">hémospermie</span> habituelle dans <span class=\"kw-clinique\">les</span> <strong>semaines</strong> suivant le geste<br>\n              <strong>Rare :</strong> rétention d'urine (&lt;<span class=\"kw-chiffre\"> 1 %</span>), surtout si SBAU préexistants\n            </td>\n          </tr>\n          <tr>\n            <td>Complication la plus grave</td>\n            <td>\n              <strong><span class=\"kw-alerte\">Prostatite aiguë iatrogène</span></strong> (<span class=\"kw-chiffre\">5 %</span>, dont <span class=\"kw-chiffre\">3 %</span> d'infections fébriles)<br>\n              <strong>CAT :</strong> <span class=\"kw-alerte\">urgence</span> ⇒ <strong><span class=\"kw-alerte\">hospitalisation</span></strong> + <span class=\"kw-bio\">ECBU</span> + <span class=\"kw-bio\">hémocultures</span> + <span class=\"kw-ttt\">antibiothérapie</span> probabiliste (<strong><span class=\"kw-ttt\">C3G injectables</span> + <span class=\"kw-ttt\">Amikacine</span></strong>)<br>\n              <strong>Risque :</strong> peut mettre en jeu le <span class=\"kw-alerte\">pronostic vital</span> (<span class=\"kw-clinique\">septicémie</span>, voire décès)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> vitale.</strong> <span class=\"kw-alerte\">Prostatite aiguë iatrogène post-biopsies (5 %)</span> = urgence médicale → <span class=\"kw-alerte\">hospitalisation</span> + <span class=\"kw-bio\">ECBU</span> + <span class=\"kw-bio\">hémocultures</span> + <strong><span class=\"kw-ttt\">C3G IV</span> + <span class=\"kw-ttt\">Amikacine</span></strong> . Risque de <span class=\"kw-clinique\">septicémie</span> et de décès en cas de retard.</div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">4) Imagerie</h4>\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Indication / Place</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Échographie</span> endorectale</strong></td>\n            <td>\n              <strong>Utilités :</strong> calcul du volume prostatique ; <strong>guidage des biopsies</strong> (systématique)<br>\n              <strong>NON ❌ :</strong> <span class=\"kw-ci\">aucun intérêt pour la détection du cancer ❌</span> (Se/Sp faibles) ; <span class=\"kw-ci\">aucun intérêt pour le bilan d'extension ❌</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">IRM</span> multiparamétrique de la prostate</strong></td>\n            <td>\n              <strong>Séquences :</strong> morphologiques <strong><span class=\"kw-imagerie\">T2</span></strong> + fonctionnelles de <strong><span class=\"kw-imagerie\">perfusion</span></strong> et <strong><span class=\"kw-imagerie\">diffusion</span></strong><br>\n              <strong>Indication :</strong> dès que la décision de biopsies est posée, à réaliser <strong>AVANT <span class=\"kw-clinique\">les</span> biopsies</strong> ; délai <span class=\"kw-chiffre\">≥ 2 mois</span> après biopsies pour le <span class=\"kw-def\">bilan d'extension</span> local<br>\n              <strong>Objectif :</strong> échantillonner la prostate (<span class=\"kw-ci\">objectif n'est PAS de poser l'indication de biopsie ❌</span>)<br>\n              <strong>Interprétation :</strong> par secteur, échelle 1 à 5 — <strong><span class=\"kw-imagerie\">PI-RADS</span></strong> (objective) ou échelle de <strong>Likert</strong> (subjective)<br>\n              <strong>Conséquences :</strong> si normale, biopsies restent indiquées ; si <span class=\"kw-imagerie\">PI-RADS ≥ 3</span> en zones non échantillonnées ⇒ biopsies ciblées supplémentaires\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TDM</span> thoraco-abdomino-pelvien injectée</strong></td>\n            <td>\n              <strong>Indication :</strong> formes à <strong>haut risque</strong> et formes <strong>métastatiques</strong> (lésions osseuses ou viscérales)<br>\n              <strong>NON ❌ :</strong> <span class=\"kw-ci\">TDM AP n'a pas de place pour le bilan d'extension local ❌</span> sauf CI à l'<span class=\"kw-imagerie\">IRM</span> (recherche d'<span class=\"kw-bio\">envahissement</span> ganglionnaire)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Tomoscintigraphie osseuse</strong></td>\n            <td>\n              <strong>Type :</strong> phosphonates marqués au <strong><span class=\"kw-imagerie\">technétium-99m</span></strong> (SPECT) couplée à <span class=\"kw-imagerie\">TDM</span> osseux<br>\n              <strong>Place :</strong> <strong>examen de référence pour le diagnostic des métastases osseuses</strong><br>\n              <strong>Indications :</strong> douleurs osseuses (quel que soit le <span class=\"kw-bio\">PSA</span>) ; patients à <strong>risque intermédiaire</strong> et à <strong>haut risque</strong> d'Amico<br>\n              <strong>NON ❌ :</strong> <span class=\"kw-ci\">non indiquée chez les patients à faible risque d'Amico ❌</span> (sauf douleurs osseuses)\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TEP</span> au <span class=\"kw-imagerie\">18F-choline</span></strong></td>\n            <td>\n              <strong>Atout :</strong> détection précoce de lésions osseuses infra-radiologiques (intramédullaires)<br>\n              <strong>Performance :</strong> meilleure spécificité notamment pour des <span class=\"kw-bio\">PSA</span> <span class=\"kw-chiffre\">&lt; 10 ng/mL</span> ; plus Se / Sp que <span class=\"kw-imagerie\">scintigraphie</span> + <span class=\"kw-imagerie\">IRM</span> pour <span class=\"kw-clinique\">les</span> lésions précoces<br>\n              <strong>Place :</strong> non recommandée systématiquement (différences de performance insuffisantes)\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TEP</span>-<span class=\"kw-imagerie\">PSMA</span></strong></td>\n            <td>\n              <strong>Performance :</strong> supérieure à <span class=\"kw-imagerie\">scintigraphie</span> + <span class=\"kw-imagerie\">TDM</span> pour détection des métastases ganglionnaires et osseuses<br>\n              <strong>Place en France :</strong> <span class=\"kw-chiffre\">ATU</span> (autorisation temporaire d'utilisation) pour <strong>récidive <span class=\"kw-ttt\">biologique</span></strong> sans métastase sur <span class=\"kw-imagerie\">TEP</span>-choline ; <strong>bilan optionnel</strong> dans <span class=\"kw-clinique\">les</span> formes à <strong>haut risque</strong> (et examen de référence en cas de discordance bilan conventionnel)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">5) Diagnostic histologique — Gleason, ISUP, Amico</h4>\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-def\">Score</span></th><th>Définition / Échelle</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Score</span> de <span class=\"kw-bio\">Gleason</span></strong></td>\n            <td>\n              <strong>Principe :</strong> caractérise le degré de <span class=\"kw-bio\">différenciation</span> <span class=\"kw-etio\">tumorale</span><br>\n              <strong>Grades :</strong> 1 à 5 ; <strong>grades 1-2 jamais retenus</strong> (cancer ≥ <span class=\"kw-def\">grade</span> 3)<br>\n              <strong>Calcul sur biopsies :</strong> grade le <strong>plus représenté</strong> + grade le <strong>plus élevé</strong> des autres types présents<br>\n              <strong>Calcul sur prostatectomie :</strong> addition des <strong><span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> g</span>rades <span class=\"kw-clinique\">les</span> plus représentés</strong><br>\n              <strong>Extrêmes :</strong> Gleason 6 = excellent <span class=\"kw-def\">pronostic</span> (aucun décès) ; Gleason 10 = quasi systématiquement létal<br>\n              <strong>Subdivision du Gleason 7 :</strong> 3+4 (moins agressif, ISUP 2) ; 4+3 (plus agressif, ISUP 3)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Groupes <span class=\"kw-bio\">ISUP</span></strong></td>\n            <td>\n              Groupe 1 = Gleason 6 ; Groupe 2 = Gleason 3+4 ; Groupe 3 = Gleason 4+3 ; Groupe 4 = Gleason 8 ; Groupe 5 = Gleason 9-10\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Classification</span> d'<span class=\"kw-bio\">Amico</span></strong></td>\n            <td>\n              <strong>Faible risque :</strong> <span class=\"kw-bio\">PSA</span> <span class=\"kw-chiffre\">&lt; 10 ng/mL</span> ET ISUP 1 (Gleason 6) ET <span class=\"kw-def\">stade</span> T1c/T2a<br>\n              <strong>Risque intermédiaire :</strong> <span class=\"kw-bio\">PSA</span> <span class=\"kw-chiffre\">10-20 ng/mL</span> OU ISUP 2-3 (Gleason 7) OU stade T2b<br>\n              <strong>Haut risque :</strong> <span class=\"kw-bio\">PSA</span> <span class=\"kw-chiffre\">&gt; 20 ng/mL</span> OU ISUP 4-5 (Gleason 8-10) OU stade T2c\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">6) <span class=\"kw-def\">Bilan d'extension</span> par classe d'Amico</h4>\n      <table >\n        <thead>\n          <tr>\n            <th>Classe d'Amico</th>\n            <th>Définition</th>\n            <th>Bilan systématique</th>\n            <th>Bilan optionnel</th>\n            <th>Moyens thérapeutiques</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Faible risque</strong></td>\n            <td><span class=\"kw-bio\">PSA</span> <span class=\"kw-chiffre\">&lt; 10 ng/mL</span> ET <span class=\"kw-bio\">ISUP 1</span> (Gleason 6) ET <span class=\"kw-def\">stade</span> <span class=\"kw-chiffre\">T1c/T2a</span> (impalpable ou <span class=\"kw-chiffre\">≤ 50 %</span> d'<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span> l</span>obe)</td>\n            <td><span class=\"kw-imagerie\">IRM prostatique et pelvienne</span> (délai <span class=\"kw-chiffre\">≥ 2 mois</span> après biopsies)</td>\n            <td><span class=\"kw-imagerie\">Tomoscintigraphie osseuse</span> (T99m, SPECT) si <span class=\"kw-clinique\">douleur osseuse</span></td>\n            <td>Abstention-<span class=\"kw-def\">surveillance</span> (si survie <span class=\"kw-chiffre\">&lt; 10 ans</span>) ; <strong>surveillance active</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Risque intermédiaire</strong></td>\n            <td><span class=\"kw-bio\">PSA</span> <span class=\"kw-chiffre\">10-20 ng/mL</span> OU <span class=\"kw-bio\">ISUP 2-3</span> (Gleason 7) OU <span class=\"kw-def\">stade</span> <span class=\"kw-chiffre\">T2b</span> (&gt;<span class=\"kw-chiffre\"> 50 %</span> d'<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span> l</span>obe)</td>\n            <td><span class=\"kw-imagerie\">IRM prostatique et pelvienne</span> + <span class=\"kw-imagerie\">tomoscintigraphie osseuse</span></td>\n            <td>—</td>\n            <td>Abstention-<span class=\"kw-def\">surveillance</span> (si survie &lt;<span class=\"kw-chiffre\"> 10 ans</span>) ; <strong>prostatectomie totale + curage</strong> ; <strong>curiethérapie</strong> exclusive (si <span class=\"kw-bio\">PSA</span> 10-15 ET ISUP 2) ; <strong><span class=\"kw-ttt\">radiothérapie</span> + hormonothérapie <span class=\"kw-chiffre\">6 mois</span></strong> (si survie &gt;<span class=\"kw-chiffre\"> 10 ans</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Haut risque</strong></td>\n            <td><span class=\"kw-bio\">PSA</span> <span class=\"kw-chiffre\">&gt; 20 ng/mL</span> OU <span class=\"kw-bio\">ISUP 4-5</span> (Gleason 8-10) OU <span class=\"kw-def\">stade</span> <span class=\"kw-chiffre\">T2c</span> (atteinte des <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> l</span>obes)</td>\n            <td><span class=\"kw-imagerie\">IRM prostatique et pelvienne</span> + <span class=\"kw-imagerie\">tomoscintigraphie osseuse</span> + <span class=\"kw-imagerie\">TDM TAP injectée</span></td>\n            <td><span class=\"kw-imagerie\">TEP-PSMA</span> ou <span class=\"kw-imagerie\">TEP 18F-choline</span></td>\n            <td>Abstention-<span class=\"kw-def\">surveillance</span> (si survie &lt;<span class=\"kw-chiffre\"> 10 ans</span>) ; <strong>prostatectomie totale + curage</strong> (en association avec autres traitements) ; <strong><span class=\"kw-ttt\">radiothérapie</span> + hormonothérapie adjuvante <span class=\"kw-chiffre\">≥ 18 mois</span></strong> (jusqu'à<span class=\"kw-chiffre\"> 36 mois</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Métastases</strong> <em>(ne fait pas partie d'Amico)</em></td>\n            <td><span class=\"kw-chiffre\">M1</span> (ganglions non régionaux, os, autres sites)</td>\n            <td><span class=\"kw-imagerie\">Tomoscintigraphie osseuse</span> + <span class=\"kw-imagerie\">TDM TAP injectée</span></td>\n            <td><span class=\"kw-imagerie\">IRM prostatique et pelvienne</span> ; <span class=\"kw-imagerie\">TEP-PSMA</span> ou <span class=\"kw-imagerie\">TEP 18F-choline</span></td>\n            <td>Hormonothérapie à vie (cf. obj-6)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Timing <span class=\"kw-imagerie\">IRM</span> mp.</strong> L'<span class=\"kw-imagerie\">IRM</span> multiparamétrique doit être réalisée <strong>AVANT</strong> <span class=\"kw-clinique\">les</span> biopsies (pour optimiser le ciblage). Si elle est faite après (ou pour le <span class=\"kw-def\">bilan d'extension</span> local post-biopsies), attendre <span class=\"kw-chiffre\">≥ 2 mois</span> pour éviter les artefacts cicatriciels qui simulent une extension extra-prostatique.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 292 — Diagnostic des cancers · 326 — Cadre réglementaire de la prescription et reco pour bon usage</em></p>","frequence":14,"liens":[{"href":"https://radiopaedia.org/articles/prostate-cancer-3","label":"Radiopaedia : Prostate cancer 3"}]},{"id":"310-7","rang":"B","rubrique":"Prise en charge","titre":"Connaître les grands principes des différentes prises en charge au stade localisé","contenu":"<p><strong>Deuxième objectif majeur de l'item</strong> (12 ⭐ QCM EDN). Stratification thérapeutique en <strong><span class=\"kw-def\">RCP</span> obl<span class=\"kw-chiffre\">iga</span>toire</strong> selon la <span class=\"kw-def\">classification</span> d'<strong><span class=\"kw-bio\">Amico</span></strong>, intégrant l'espérance de vie, <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">comorbidités</span> et le souhait du patient. Cinq grandes modalités à connaître : <strong><span class=\"kw-def\">surveillance</span></strong>, <strong>prostatectomie totale</strong>, <strong><span class=\"kw-ttt\">radiothérapie</span> externe</strong>, <strong>curiethérapie</strong>, <strong>HIFU</strong>, complétées par l'<strong>hormonothérapie</strong>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">1) Stratification thérapeutique par groupe d'Amico (<span class=\"kw-def\">RCP</span> obl<span class=\"kw-chiffre\">iga</span>toire)</h4>\n      <table >\n        <thead>\n          <tr>\n            <th>Risque</th>\n            <th><span class=\"kw-def\">Surveillance</span> active</th>\n            <th>Prostatectomie + curage</th>\n            <th><span class=\"kw-ttt\">Radiothérapie</span> externe</th>\n            <th>Curiethérapie</th>\n            <th>HIFU</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Faible</strong></td>\n            <td><strong>Recommandée</strong></td>\n            <td>Optionnelle</td>\n            <td>Optionnelle (sans hormonothérapie associée)</td>\n            <td>Optionnelle</td>\n            <td>Expérimental</td>\n          </tr>\n          <tr>\n            <td><strong>Intermédiaire</strong></td>\n            <td>Optionnelle</td>\n            <td><strong>Recommandée</strong> (± curage)</td>\n            <td><strong>Recommandée</strong> + <span class=\"kw-ttt\">hormonothérapie 6 mois</span></td>\n            <td>Optionnelle (si <span class=\"kw-bio\">PSA</span> 10-15 ET ISUP 2)</td>\n            <td>Expérimental</td>\n          </tr>\n          <tr>\n            <td><strong>Haut</strong></td>\n            <td><span class=\"kw-ci\">Non recommandée ❌</span></td>\n            <td><strong>Recommandée</strong> (+ curage)</td>\n            <td><strong>Recommandée</strong> + <span class=\"kw-ttt\">hormonothérapie 18 à 36 mois</span></td>\n            <td><span class=\"kw-ci\">Non recommandée ❌</span></td>\n            <td><span class=\"kw-ci\">Non recommandé ❌</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Toutes catégories :</strong> abstention-<span class=\"kw-def\">surveillance</span> discutée si probabilité de survie <span class=\"kw-chiffre\">&lt; 10 ans</span>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">2) <span class=\"kw-def\">Surveillance</span> — 2 modalités à ne pas confondre</h4>\n      <table >\n        <thead>\n          <tr><th></th><th>Abstention-surveillance (palliatif)</th><th>Surveillance active (curatif)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Visée</td>\n            <td><strong><span class=\"kw-alerte\">Palliative</span></strong></td>\n            <td><strong>Curative</strong></td>\n          </tr>\n          <tr>\n            <td>Indication</td>\n            <td>Patients à survie limitée (<span class=\"kw-def\">comorbidités</span> lourdes, espérance de vie <span class=\"kw-chiffre\">&lt; 10 ans</span>)</td>\n            <td>Cancers de la prostate à <strong>faible risque</strong> : <span class=\"kw-bio\">PSA</span> <span class=\"kw-chiffre\">&lt; 10</span> ET <span class=\"kw-bio\">Gleason 6</span> ET <span class=\"kw-chiffre\">&lt; 3</span> biopsies positives ET longueur de cancer par <span class=\"kw-ttt\">biopsie</span> <span class=\"kw-chiffre\">&lt; 3 mm</span></td>\n          </tr>\n          <tr>\n            <td>Principe</td>\n            <td>Traitement <strong>uniquement à l'apparition de symptômes</strong> (<span class=\"kw-clinique\">évolution</span> locorégionale ou métastatique)</td>\n            <td>Retarder le traitement d'une tumeur peu agressive, jusqu'au moment où elle deviendrait agressive — tout en restant dans la fenêtre de curabilité</td>\n          </tr>\n          <tr>\n            <td>Modalités</td>\n            <td><span class=\"kw-def\">Surveillance</span> clinique simple</td>\n            <td>\n              <strong>TR + <span class=\"kw-bio\">PSA</span> :</strong> <span class=\"kw-chiffre\">≥ 2 fois/an</span> (<span class=\"kw-chiffre\">3-6 mois</span>)<br>\n              <strong><span class=\"kw-imagerie\">IRM</span> puis biopsies de confirmation :</strong> dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">12-18 premiers mois</span><br>\n              <strong>Sortie :</strong> <span class=\"kw-def\">grade</span> <span class=\"kw-bio\">ISUP 2</span> sur biopsies de contrôle\n            </td>\n          </tr>\n          <tr>\n            <td>Probabilité de rester en SA à<span class=\"kw-chiffre\"> 5 ans</span></td>\n            <td>—</td>\n            <td><span class=\"kw-chiffre\">~60 %</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Discriminant clé QCM.</strong> <strong><span class=\"kw-def\">Surveillance</span> active = curatif</strong> (faible risque, TR + <span class=\"kw-bio\">PSA</span> + biopsies de contrôle) ≠ <strong>Abstention-surveillance = <span class=\"kw-alerte\">palliatif</span></strong> (survie limitée, traitement uniquement à l'apparition de symptômes). Ne pas confondre.</div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">3) Prostatectomie totale (traitement curatif)</h4>\n      <table >\n        <thead>\n          <tr><th></th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Indications</td>\n            <td>Absence de métastases ; tumeur intermédiaire (selon <span class=\"kw-def\">comorbidités</span> et espérance de vie <span class=\"kw-chiffre\">&gt; 10 ans</span>) ; tumeur à <strong>haut risque</strong> dans un traitement multimodal</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ci\">Contre-indications</span></td>\n            <td>Pas de CI de principe (sauf <span class=\"kw-ci\">CI formelle à l'anesthésie</span>) ; <span class=\"kw-ci\">trouble urinaire pré-existant</span>, <span class=\"kw-ci\">ATCD de chirurgie prostatique</span>, <span class=\"kw-ci\">hyperactivité vésicale</span> font discuter l'indication (risque d'incontinence accru)</td>\n          </tr>\n          <tr>\n            <td>Modalités</td>\n            <td>\n              <strong>Voies :</strong> ouverte, laparoscopique, laparoscopique robot-assistée (<strong>pas de supériorité démontrée</strong>)<br>\n              <strong>Gestes :</strong> <span class=\"kw-ttt\">exérèse</span> complète de la prostate + vésicules séminales ; anastomose col vésical-urètre<br>\n              <strong><span class=\"kw-ttt\">Curage ganglionnaire</span> :</strong> ilio-obturateurs, iliaques internes et externes jusqu'à la bifurcation iliaque ⇒ <strong>risque intermédiaire et haut</strong> ; <span class=\"kw-ci\">inutile en faible risque ❌</span> (ganglion métastatique exceptionnel)<br>\n              <strong>Préservation des bandelettes neurovasculaires :</strong> à discuter si tumeur faible/intermédiaire chez patient demandeur avec fonction érectile normale (réduit le risque de dysérection)\n            </td>\n          </tr>\n          <tr>\n            <td>Bénéfices</td>\n            <td>\n              Recul très long des résultats<br>\n              Contrôle local et à distance quelle que soit l'agressivité<br>\n              Rattrapage possible après échec de <span class=\"kw-ttt\">radiothérapie</span> (risques fonctionnels et chirurgicaux alors plus élevés)<br>\n              Association possible à <span class=\"kw-imagerie\">RT</span> et hormonothérapie pour <span class=\"kw-clinique\">les</span> formes agressives\n            </td>\n          </tr>\n          <tr>\n            <td>Risques constants ou fréquents ⚠️</td>\n            <td>\n              <strong><span class=\"kw-clinique\">Anéjaculation</span> <span class=\"kw-chiffre\">100 %</span></strong> et infertilité (proposer une <strong>conservation de sperme</strong> ; rappeler que l'orgasme ne nécessite pas d'éjaculation)<br>\n              <strong><span class=\"kw-clinique\">Dysfonction érectile</span> <span class=\"kw-chiffre\">~70 %</span></strong> — complication la plus fréquente (récupération dépend de la qualité d'érection préopératoire, de la motivation, de la conservation des bandelettes)<br>\n              <strong><span class=\"kw-clinique\">Incontinence urinaire</span></strong> fréquente, régressant en quelques semaines/mois ; <strong>définitive dans <span class=\"kw-chiffre\">5-10 %</span></strong>\n            </td>\n          </tr>\n          <tr>\n            <td>Complications opératoires (rares)</td>\n            <td>Hémorragie peropératoire ; plaie rectale ; lymphocèle (curage) ; <span class=\"kw-clinique\">fistule</span> sur l'anastomose ; sténose vésico-urétrale (&lt;<span class=\"kw-chiffre\"> 1 %</span>) ; risques anesthésiques</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">4) <span class=\"kw-ttt\">Radiothérapie</span> externe</h4>\n      <table >\n        <thead>\n          <tr><th></th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Modalités</td>\n            <td><span class=\"kw-clinique\">Irradiation</span> guidée par l'image, en <strong>modulation d'intensité</strong> ; dose <span class=\"kw-chiffre\">≥ 75 Gy</span> ; 1 séance de <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> G</span>y/j pendant <span class=\"kw-chiffre\">7-8 semaines</span> (ou hypofractionnement)</td>\n          </tr>\n          <tr>\n            <td>Indications curatives</td>\n            <td>\n              Absence de métastases<br>\n              <strong>Risque intermédiaire</strong> + <span class=\"kw-ttt\">hormonothérapie adjuvante 6 mois</span> (si survie &gt;<span class=\"kw-chiffre\"> 10 ans</span>)<br>\n              <strong>Haut risque</strong> + <span class=\"kw-ttt\">hormonothérapie adjuvante ≥ 18 mois</span> (jusqu'à<span class=\"kw-chiffre\"> 36 mois</span>)\n            </td>\n          </tr>\n          <tr>\n            <td>Indications adjuvantes / rattrapage</td>\n            <td>Tumeurs à très haut risque (traitement multimodal) ; récidive après <span class=\"kw-ttt\">chirurgie</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ci\">Contre-indications</span></td>\n            <td><span class=\"kw-ci\">ATCD d'irradiation pelvienne</span> ; <span class=\"kw-ci\">maladie inflammatoire rectale active</span> ; <span class=\"kw-ci\">sclérodermie</span> ; <span class=\"kw-ci\">impossibilité de maintien de la position</span></td>\n          </tr>\n          <tr>\n            <td>ES précoces (réversibles en <span class=\"kw-chiffre\">3 semaines</span>)</td>\n            <td><span class=\"kw-clinique\">Dysurie</span> ; <span class=\"kw-clinique\">pollakiurie</span> ; <span class=\"kw-clinique\">accélération du transit</span></td>\n          </tr>\n          <tr>\n            <td>ES tardifs (définitifs)</td>\n            <td>\n              <span class=\"kw-clinique\">Sténose urétrale</span><br>\n              <span class=\"kw-clinique\">Cystite radique</span> (parfois <span class=\"kw-etio\">hémorragique</span>)<br>\n              <span class=\"kw-clinique\">Rectite radique</span><br>\n              <strong><span class=\"kw-clinique\">Dysfonction érectile</span></strong> = complication la plus fréquente (<span class=\"kw-chiffre\">&gt; 70 %</span>), <strong>majorée par l'hormonothérapie concomitante</strong>\n            </td>\n          </tr>\n          <tr>\n            <td>Précaution</td>\n            <td><strong>Adénome obstructif symptomatique</strong> ⇒ discuter un traitement préalable avant l'<span class=\"kw-clinique\">irradiation</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">5) Curiethérapie interstitielle exclusive</h4>\n      <table >\n        <thead>\n          <tr><th></th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Principe</td>\n            <td>Implantation permanente de grains d'<strong><span class=\"kw-ttt\">iode 125</span></strong> par voie périnéale (ou <span class=\"kw-ttt\">iridium 192</span> temporaire = curiethérapie à haut débit)</td>\n          </tr>\n          <tr>\n            <td>Indications</td>\n            <td>Groupe à <strong>risque intermédiaire</strong> avec <span class=\"kw-bio\">PSA</span> <span class=\"kw-chiffre\">10-15 ng/mL</span> ET <span class=\"kw-bio\">ISUP 2</span> ; principalement utilisée en <strong>traitement exclusif</strong></td>\n          </tr>\n          <tr>\n            <td>Modalités</td>\n            <td>1 séance unique (avantage / <span class=\"kw-imagerie\">RT</span> externe) ; anesthésie générale ou rachi-anesthésie ; guidage par <span class=\"kw-imagerie\">échographie</span> endorectale</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ci\">Contre-indications</span> spécifiques</td>\n            <td>CI communes avec la <span class=\"kw-imagerie\">RT</span> externe (ATCD <span class=\"kw-clinique\">irradiation</span>, <span class=\"kw-clinique\">MICI</span> active, <span class=\"kw-clinique\">sclérodermie</span>) + <span class=\"kw-ci\">ATCD de résection endo-urétrale (RTUP)</span> + <span class=\"kw-ci\">volume prostate &gt; 60 mL</span> + <span class=\"kw-ci\">lobe médian symptomatique</span> + <span class=\"kw-ci\">symptômes urinaires marqués</span></td>\n          </tr>\n          <tr>\n            <td>Bénéfices / Risques</td>\n            <td>\n              <strong>Bénéfices :</strong> 1 séance unique ; option avec le plus faible risque de <span class=\"kw-clinique\">dysérection</span> (<span class=\"kw-chiffre\">&lt; 30 %</span>) ; ES de <span class=\"kw-def\">grade</span> &gt; 2 plus rares qu'en <span class=\"kw-imagerie\">RT</span> externe<br>\n              <strong>ES :</strong> identiques à la RT externe (sténose urétrale, <span class=\"kw-clinique\">cystite</span> radique, rectite radique, dysérection)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">6) HIFU (ultrasons focalisés de haute intensité) — en cours d'évaluation</h4>\n      <table >\n        <thead>\n          <tr><th></th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Principe</td>\n            <td>Destruction du tissu prostatique par ultrasons focalisés</td>\n          </tr>\n          <tr>\n            <td>Indications</td>\n            <td>Indications voisines de la curiethérapie, <strong>plutôt &gt; <span class=\"kw-chiffre\">70 ans</span></strong> ou en cas de <span class=\"kw-ci\">CI à la radiothérapie</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Morbidité</span> en traitement de rattrapage post-<span class=\"kw-imagerie\">RT</span> (élevée)</td>\n            <td>\n              <span class=\"kw-clinique\">Sténose de l'urètre prostatique</span> : <span class=\"kw-chiffre\">~20 %</span><br>\n              <span class=\"kw-clinique\">Incontinence urinaire</span> : <span class=\"kw-chiffre\">5-10 %</span><br>\n              <span class=\"kw-clinique\">Dysérection</span> : <span class=\"kw-chiffre\">50-70 %</span><br>\n              <span class=\"kw-clinique\">Fistule prostato-rectale</span> : exceptionnelle\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">7) Hormonothérapie de 1<sup>re</sup> génération (suppression androgénique)</h4>\n      <table >\n        <thead>\n          <tr><th>Moyen</th><th>Principe</th><th>Délai de castration</th><th>Modalités / Notes</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Castration chirurgicale</strong></td>\n            <td>Orchidectomie (ablation des 2 testicules) ou pulpectomie (ablation de la pulpe testiculaire)</td>\n            <td><span class=\"kw-chiffre\">12 h</span></td>\n            <td>Surtout chez <span class=\"kw-clinique\">les</span> patients <strong>métastatiques</strong> avec problème d'observance ; <span class=\"kw-ci\">traitement irréversible ❌</span> ⇒ non proposé en adjuvant de la <span class=\"kw-ttt\">radiothérapie</span></td>\n          </tr>\n          <tr>\n            <td><strong>Antagonistes LH-RH</strong></td>\n            <td>Blocage direct des récepteurs hypophysaires de la LH-RH ⇒ arrêt de sécrétion de LH/FSH ⇒ arrêt des cellules de Leydig</td>\n            <td><span class=\"kw-chiffre\">48-72 h</span></td>\n            <td>\n              DCI : <strong><span class=\"kw-ttt\">dégarélix</span></strong><br>\n              Injection sous-cutanée mensuelle<br>\n              <strong>Réversible</strong> ; <strong><span class=\"kw-alerte\">pas d'effet flare-up ✅</span></strong>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Agonistes LH-RH</strong></td>\n            <td>Saturation des récepteurs hypophysaires : stimulation initiale puis arrêt différé de la stimulation pulsatile ⇒ disparition de la stimulation des cellules de Leydig</td>\n            <td><span class=\"kw-chiffre\">2-4 semaines</span></td>\n            <td>\n              DCI : <strong><span class=\"kw-ttt\">goséréline</span></strong>, <strong><span class=\"kw-ttt\">leuproréline</span></strong>, <strong><span class=\"kw-ttt\">triptoréline</span></strong><br>\n              Injection sous-cutanée mensuelle / trimestrielle / semestrielle<br>\n              <strong>Réversible</strong> ; <strong><span class=\"kw-alerte\">risque de flare-up</span></strong> (pic de testostéronémie <span class=\"kw-chiffre\">J1</span>-J5)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Anti-androgènes non stéroïdiens (1<sup>re</sup> génération)</strong></td>\n            <td>Blocage direct du récepteur des androgènes au niveau périphérique (notamment prostatique)</td>\n            <td>Non applicable</td>\n            <td>\n              Forme orale quotidienne<br>\n              <strong>Indication :</strong> en <strong>association</strong> avec agoniste LH-RH pour <strong>prévenir le flare-up</strong> pendant <span class=\"kw-chiffre\">2-3 semaines</span><br>\n              <span class=\"kw-ci\">Utilisation prolongée &gt; 1 mois sans intérêt démontré ❌</span><br>\n              <span class=\"kw-ci\">Monothérapie non recommandée ❌</span> — <strong>CI formelle chez le patient métastatique</strong>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> vitale — flare-up.</strong> <span class=\"kw-clinique\">Les</span> agonistes LH-RH provoquent un <span class=\"kw-alerte\">pic de testostéronémie J1-J5</span> (flare-up). En cas de <strong>métastases vertébrales</strong> (risque de <span class=\"kw-alerte\">compression médullaire</span>) ou d'<strong>obstruction des voies urinaires</strong>, <strong>blocage androgénique complet impératif</strong> : anti-androgène <strong>avant ou en même temps</strong> que le 1<sup>er</sup> agoniste, pendant <span class=\"kw-chiffre\">2-3 semaines</span>, jusqu'à atteinte de la castration médicale (testostéronémie <span class=\"kw-chiffre\">≤ 0,5 ng/mL</span>).</div>\n      <div class=\"callout callout-warn\"><strong>CI formelle.</strong> <span class=\"kw-ci\">Anti-androgènes non stéroïdiens en monothérapie chez le patient métastatique ❌</span>. Toujours en association avec un agoniste LH-RH.</div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Objectifs, indications, durée et bilan pré-hormonothérapie</h4>\n      <table >\n        <thead>\n          <tr><th></th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Objectif <span class=\"kw-ttt\">biologique</span></td>\n            <td><strong>Testostéronémie <span class=\"kw-chiffre\">&lt; 50 ng/dL</span></strong> (ou <span class=\"kw-chiffre\">&lt; 0,5 ng/mL</span>) 🎯</td>\n          </tr>\n          <tr>\n            <td>Durée selon indication</td>\n            <td>\n              <strong>Risque intermédiaire (adjuvant <span class=\"kw-imagerie\">RT</span>) :</strong> <span class=\"kw-chiffre\">6 mois</span><br>\n              <strong>Haut risque (adjuvant RT) :</strong> <span class=\"kw-chiffre\">≥ 18 mois</span>, jusqu'à <span class=\"kw-chiffre\">36 mois</span> ; hormonothérapie de 2<sup>e</sup> génération (<span class=\"kw-ttt\">acétate d'abiratérone</span>) dans certaines formes à très haut risque (suspicion N+ initial)<br>\n              <strong>Métastatique / récidive <span class=\"kw-ttt\">biologique</span> :</strong> <strong>à vie</strong>\n            </td>\n          </tr>\n          <tr>\n            <td>Bilan pré-hormonothérapie</td>\n            <td>\n              <span class=\"kw-etio\">FRCV</span>, ostéoporose, chutes, troubles de l'humeur, troubles de la sexualité<br>\n              PA, poids, taille, IMC, périmètre abdominal<br>\n              <strong>Examens :</strong> <span class=\"kw-bio\">glycémie</span> à jeun + <span class=\"kw-bio\">bilan lipidique</span> ; <span class=\"kw-bio\">vitamine D</span> + <strong>ostéodensitométrie</strong>\n            </td>\n          </tr>\n          <tr>\n            <td>Effets secondaires (dès <span class=\"kw-chiffre\">6 mois</span>, croissant avec la durée)</td>\n            <td>\n              <span class=\"kw-clinique\">Fatigue</span> ; <span class=\"kw-clinique\">bouffées de chaleur</span> (<span class=\"kw-chiffre\">50-80 %</span>)<br>\n              <span class=\"kw-clinique\">Dysérection</span> (<span class=\"kw-chiffre\">90-95 %</span>), baisse de libido, atrophie OGE<br>\n              <span class=\"kw-clinique\">Gynécomastie</span><br>\n              <strong><span class=\"kw-alerte\">Déperdition du capital osseux</span> :</strong> précoce (<span class=\"kw-chiffre\">6-12 mois</span>), <strong>profonde</strong> (plus intense que l'ostéopénie post-ménopause)<br>\n              <span class=\"kw-clinique\">Sarcopénie et chutes</span><br>\n              <strong><span class=\"kw-etio\">FRCV</span> / syndrome pseudométabolique :</strong> <span class=\"kw-clinique\">insulinorésistance</span>, <span class=\"kw-clinique\">masse</span> grasse ↑, <span class=\"kw-bio\">LDL</span> ↑, <span class=\"kw-bio\">HDL</span> ↑<br>\n              <strong>Troubles psychologiques :</strong> <span class=\"kw-alerte\">risque anxio-dépressif</span> ; <span class=\"kw-alerte\">détérioration cognitive</span>\n            </td>\n          </tr>\n          <tr>\n            <td>NON ❌</td>\n            <td><span class=\"kw-ci\">Pas d'arthralgie ❌</span> et <span class=\"kw-ci\">pas de thrombose ❌</span> (≠ hormonothérapie du cancer du sein)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Mémo durées HT adjuvante : 6 — 18-36 — à vie.</strong><span class=\"kw-chiffre\"> 6 mois</span> si risque intermédiaire ; <span class=\"kw-chiffre\">≥ 18 mois</span> (jusqu'à 36) si haut risque ; à vie si métastatique ou récidive <span class=\"kw-ttt\">biologique</span>.</div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">8) <span class=\"kw-def\">Suivi</span> après traitement local (hors surveillance active)</h4>\n      <table >\n        <thead>\n          <tr><th></th><th>Après prostatectomie radicale</th><th>Après <span class=\"kw-imagerie\">RT</span> externe (± HT) ou curiethérapie</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Examens</td>\n            <td><strong><span class=\"kw-bio\">PSA</span> seul</strong></td>\n            <td><strong><span class=\"kw-clinique\">TR</span> + <span class=\"kw-bio\">PSA</span></strong></td>\n          </tr>\n          <tr>\n            <td>Rythme</td>\n            <td><span class=\"kw-chiffre\">6 semaines</span>, <span class=\"kw-chiffre\">M3</span>, M6, M12, puis tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 mois</span> pendant <span class=\"kw-chiffre\">3 ans</span>, puis 1×/an</td>\n            <td><span class=\"kw-chiffre\">6 semaines</span>, <span class=\"kw-chiffre\">M3</span>, M6, M12, puis tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 mois</span> pendant <span class=\"kw-chiffre\">3 ans</span>, puis 1×/an (+ évaluation des toxicités spécifiques <span class=\"kw-imagerie\">RT</span> <span class=\"kw-chiffre\">≥ 1</span>×/an pendant <span class=\"kw-chiffre\">5 ans</span>)</td>\n          </tr>\n          <tr>\n            <td>Réponse complète</td>\n            <td><span class=\"kw-bio\">PSA</span> <span class=\"kw-chiffre\">&lt; 0,2 ng/mL</span> à<span class=\"kw-chiffre\"> 6 semaines</span></td>\n            <td><span class=\"kw-ci\">Pas de seuil de PSA permettant d'affirmer la réponse complète ❌</span> ; <span class=\"kw-def\">suivi</span> du <strong><span class=\"kw-bio\">PSA</span> nadir</strong> (valeur la plus basse atteinte)</td>\n          </tr>\n          <tr>\n            <td>Récidive <span class=\"kw-ttt\">biologique</span></td>\n            <td><span class=\"kw-bio\">PSA</span> <strong>&gt; <span class=\"kw-chiffre\">0,2 ng/mL</span></strong> confirmé à 1 reprise</td>\n            <td>Augmentation <strong>&gt; <span class=\"kw-chiffre\">2 ng/mL</span> au-dessus du <span class=\"kw-bio\">PSA</span> nadir</strong></td>\n          </tr>\n          <tr>\n            <td>Durée du <span class=\"kw-def\">suivi</span></td>\n            <td colspan=\"2\"><span class=\"kw-chiffre\">≥ 10 ans</span> (récidives tardives éligibles à un traitement curatif possibles)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 125 — Trouble miction - incontinence urinaire · 126 — Trouble érection · 294 — Traitement des cancers · 295 — Prise en charge d'un malade cancéreux · 322 — Décision thérapeutique personnalisée</em></p>","frequence":12}],"astuces":[],"strategie":{"urgence":"<p><strong>Pathologie indolente :</strong> <span class=\"kw-clinique\">évolution</span> <span class=\"kw-clinique\">le plus souvent asymptomatique</span> et très lente, pas d'<span class=\"kw-alerte\">urgence</span> diagnostique propre.<br><strong><span class=\"kw-clinique\">Prostatite</span> aiguë <span class=\"kw-etio\">iatrogène</span> :</strong> <span class=\"kw-alerte\">urgence médicale</span> après biopsies (<span class=\"kw-chiffre\">5 %</span>, dont <span class=\"kw-chiffre\">3 %</span> fébriles), pouvant évoluer vers une <span class=\"kw-alerte\">septicémie</span> voire le décès → <span class=\"kw-ttt\">hospitalisation + ECBU + hémocultures + antibiothérapie probabiliste (C3G injectable + amikacine)</span>.<br><strong>Compression médullaire :</strong> <span class=\"kw-alerte\">métastases rachidiennes</span> avec signes neurologiques = urgence.<br><strong>Flare-up :</strong> à l'instauration d'un <span class=\"kw-ttt\">agoniste de la LH-RH</span>, risque de <span class=\"kw-clinique\">poussée</span> <span class=\"kw-etio\">tumorale</span> si <span class=\"kw-alerte\">obstruction des voies urinaires</span> ou <span class=\"kw-alerte\">métastases vertébrales</span> → <span class=\"kw-ttt\">anti-androgène</span> associé avant ou au début du traitement (blocage androgénique complet).</p>","hospit":"<p><strong>Démarche ambulatoire :</strong> <span class=\"kw-def\">dépistage</span> et bilan menés en consultation ; <span class=\"kw-ttt\">biopsies prostatiques écho-guidées</span> réalisées en consultation (reprise d'activité dès le lendemain).<br><strong>Adressage urologue :</strong> justifié si <span class=\"kw-clinique\">TR suspect</span> (<span class=\"kw-clinique\">nodule</span> dur, irrégulier, indolore) ou <span class=\"kw-bio\">densité du PSA inquiétante</span> confirmée à 2 reprises à <span class=\"kw-chiffre\">1 mois</span> d'intervalle.<br><strong><span class=\"kw-def\">RCP</span> obl<span class=\"kw-chiffre\">iga</span>toire :</strong> toute décision thérapeutique passe en <span class=\"kw-def\">réunion de concertation pluridisciplinaire</span>.<br><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> en <span class=\"kw-alerte\">urgence</span> si <span class=\"kw-alerte\">prostatite aiguë post-biopsie</span> ou complication métastatique (<span class=\"kw-alerte\">compression médullaire</span>, <span class=\"kw-alerte\">insuffisance rénale obstructive</span>).</p>","redflags":"<ul><li><span class=\"kw-bio\">PSA</span> > <span class=\"kw-chiffre\">15-20 ng/mL</span> : <span class=\"kw-clinique\">évolution</span> <span class=\"kw-etio\">métastatique</span> suspectée → justifie un <span class=\"kw-def\">bilan d'extension</span></li><li><span class=\"kw-clinique\">Blindage pelvien</span> au toucher rectal : <span class=\"kw-bio\">envahissement</span> des organes de voisinage</li><li><span class=\"kw-clinique\">Douleurs osseuses inflammatoires</span> à prédominance nocturne : <span class=\"kw-etio\">métastases osseuses</span></li><li><span class=\"kw-clinique\">Signes neurologiques</span> (paresthésies, déficit moteur, <span class=\"kw-clinique\">syndrome de la</span> queue de cheval) : <span class=\"kw-alerte\">compression médullaire par métastases rachidiennes</span></li><li><span class=\"kw-clinique\">Anurie</span> : <span class=\"kw-alerte\">insuffisance rénale obstructive</span> par <span class=\"kw-bio\">envahissement</span> trigonal</li><li><span class=\"kw-clinique\">AEG</span> avec <span class=\"kw-bio\">anémie</span> : <span class=\"kw-bio\">envahissement</span> médullaire métastatique</li><li><span class=\"kw-clinique\">Œdème d'un membre inférieur</span>, surtout <span class=\"kw-clinique\">asymétrique</span> : extension <span class=\"kw-etio\">ganglionnaire pelvienne</span> avec compression veineuse</li></ul>","principes":"<p>Prise en charge décidée en <span class=\"kw-ttt\">RCP</span>, orientée par la <span class=\"kw-def\">classification pronostique de d'Amico</span> (<span class=\"kw-bio\">PSA</span> · <span class=\"kw-def\">grade</span> ISUP · stade T) et par l'<span class=\"kw-chiffre\">espérance de vie</span>.</p><p><strong>Faible risque</strong></p><p><span class=\"kw-ttt\">Curage ganglionnaire</span> inutile ; <span class=\"kw-ttt\">radiothérapie</span> sans hormonothérapie associée si traitement local choisi</p><ul><li><span class=\"kw-bio\">PSA < 10 ng/mL</span> ET <span class=\"kw-etio\">ISUP 1</span> (Gleason 6) ET stade T1c/T2a</li><li><span class=\"kw-ttt\">Surveillance active</span> recommandée (intention curative)</li><li><span class=\"kw-ttt\">Abstention-surveillance</span> si probabilité de survie < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">10 ans</span></span></li></ul><p><strong>Risque intermédiaire</strong></p><ul><li><span class=\"kw-bio\">PSA 10-20 ng/mL</span> OU <span class=\"kw-etio\">ISUP 2-3</span> (Gleason 7) OU <span class=\"kw-def\">stade</span> T2b</li><li><span class=\"kw-ttt\">Prostatectomie totale + curage ganglionnaire</span> si espérance de vie > <span class=\"kw-chiffre\">10 ans</span></li><li><span class=\"kw-ttt\">Radiothérapie externe + hormonothérapie adjuvante de 6 mois</span></li><li><span class=\"kw-ttt\">Curiethérapie interstitielle exclusive</span> si <span class=\"kw-bio\">PSA 10-15 ng/mL</span> et <span class=\"kw-etio\">ISUP 2</span></li></ul><p><strong>Haut risque</strong></p><ul><li><span class=\"kw-bio\">PSA > 20 ng/mL</span> OU <span class=\"kw-etio\">ISUP 4-5</span> (Gleason 8-10) OU <span class=\"kw-def\">stade</span> T2c</li><li><span class=\"kw-ttt\">Prostatectomie totale + curage</span> intégrée à un traitement multimodal</li><li><span class=\"kw-ttt\">Radiothérapie externe + hormonothérapie ≥ 18 mois</span> (jusqu'à <span class=\"kw-chiffre\">36 mois</span>)</li></ul><p><strong><span class=\"kw-def\">Stade</span> métastatique (<span class=\"kw-chiffre\">M1</span>)</strong></p><ul><li><span class=\"kw-ttt\">Suppression androgénique</span> (castration médicale ou chirurgicale) à vie</li><li>Objectif : <span class=\"kw-bio\">testostérone < 0,5 ng/mL</span> (50 ng/dL)</li><li><span class=\"kw-ci\">Anti-androgène en monothérapie contre-indiqué</span> chez le patient métastatique</li></ul>","suivi":"<p><strong>Durée :</strong> <span class=\"kw-def\">suivi</span> d'au moins <span class=\"kw-chiffre\">10 ans</span> (récidives tardives encore curables possibles).<br><strong>Après prostatectomie :</strong> <span class=\"kw-bio\">PSA</span> seul (<span class=\"kw-chiffre\">6 semaines</span>, <span class=\"kw-chiffre\">M3</span>, M6, M12, puis tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 mois</span> pendant <span class=\"kw-chiffre\">3 ans</span>, puis 1×/an) ; <span class=\"kw-etio\">récidive biologique</span> si <span class=\"kw-bio\">PSA > 0,2 ng/mL</span> confirmé à une reprise.<br><strong>Après <span class=\"kw-ttt\">radiothérapie</span> / curiethérapie :</strong> <span class=\"kw-clinique\">TR</span> + <span class=\"kw-bio\">PSA</span> ; <span class=\"kw-etio\">récidive biologique</span> si <span class=\"kw-bio\">augmentation > 2 ng/mL au-dessus du nadir</span>.<br><strong><span class=\"kw-def\">Surveillance</span> active :</strong> <span class=\"kw-clinique\">TR</span> + <span class=\"kw-bio\">PSA</span> <span class=\"kw-chiffre\">≥ 2</span>×/an, <span class=\"kw-imagerie\">IRM</span> + biopsies de confirmation à <span class=\"kw-chiffre\">12-18 mois</span> ; sortie si <span class=\"kw-etio\">ISUP 2</span> sur biopsies de contrôle.<br><strong>Sous hormonothérapie :</strong> dépister la <span class=\"kw-clinique\">déperdition osseuse</span> et le <span class=\"kw-clinique\">syndrome pseudométabolique</span> ; <span class=\"kw-bio\">kaliémie</span> + supplémentation cortisonique indispensables si acétate d'abiratérone.</p>"},"liensGlobaux":[{"href":"https://www.urofrance.org/lafu-academie/formation-du-college/referentiel-du-college-durologie-6eme-edition/chapitre-16-item-310-tumeurs-de-la-prostate/","label":"AFU — Chapitre 16 item 310 tumeurs de la prostate"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Cancer de prostate confirmé — Adénocarcinome (biopsies +) · bilan d'extension réalisé · décision en RCP","detail":"<h4>CAT — Stratification d'Amico et orientation thérapeutique (cancer de prostate localisé) — Après diagnostic histologique (biopsies +) et <span class=\"kw-def\">bilan d'extension</span>, décision en <span class=\"kw-def\">RCP</span></h4>","branches":[{"to":"q-meta","label":"Stadification TNM","color":"blue"}]},{"id":"q-meta","kind":"decision","label":"Maladie métastatique (M1) ?","branches":[{"to":"t-meta","label":"Oui — M1","color":"red"},{"to":"q-risque","label":"Non — localisé (M0)","color":"green"}]},{"id":"t-meta","kind":"terminal","label":"Hormonothérapie — suppression androgénique — Stade métastatique","color":"red","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Castration médicale</span> (agoniste / antagoniste de la LH-RH) ou <span class=\"kw-ttt\">castration chirurgicale</span> (pulpectomie), à vie</li><li>Objectif : <span class=\"kw-bio\">testostérone < 0,5 ng/mL</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Blocage androgénique complet</span> (agoniste LH-RH + <span class=\"kw-ttt\">anti-androgène</span>) si <span class=\"kw-alerte\">forte masse tumorale</span> (obstruction urinaire, métastases vertébrales) pour prévenir le <span class=\"kw-etio\">flare-up</span></li><li><span class=\"kw-ci\">Anti-androgène en monothérapie contre-indiqué</span></li></ul>"},{"id":"q-risque","kind":"decision","label":"Stratification pronostique de d'Amico — PSA · grade ISUP · stade T","branches":[{"to":"q-ev-faible","label":"Faible · PSA < 10 ET ISUP 1 ET T1c-T2a","color":"green"},{"to":"t-interm","label":"Intermédiaire · PSA 10-20 OU ISUP 2-3 OU T2b","color":"amber"},{"to":"t-haut","label":"Haut · PSA > 20 OU ISUP 4-5 OU T2c","color":"red"}]},{"id":"q-ev-faible","kind":"decision","label":"Faible risque — probabilité de survie ?","branches":[{"to":"t-active","label":"≥ 10 ans","color":"green"},{"to":"t-abstention","label":"< 10 ans","color":"amber"}]},{"id":"t-active","kind":"terminal","label":"Surveillance active — Intention curative","color":"green","detail":"<h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-clinique\">TR</span> + <span class=\"kw-bio\">PSA</span> tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 à 6 mois</span> (<span class=\"kw-chiffre\">≥ 2</span>×/an)</li><li><span class=\"kw-imagerie\">IRM</span> + biopsies de confirmation à <span class=\"kw-chiffre\">12-18 mois</span></li></ul><h4>Conduite</h4><ul><li>Sortie de <span class=\"kw-def\">surveillance</span> active si <span class=\"kw-etio\">ISUP 2</span> sur <span class=\"kw-clinique\">les</span> biopsies de contrôle</li></ul>"},{"id":"t-abstention","kind":"terminal","label":"Abstention-surveillance — Modalité palliative","color":"amber","detail":"<h4>Conduite</h4><ul><li>Traitement uniquement à l'apparition de <span class=\"kw-clinique\">symptômes</span></li><li>Réservée aux <span class=\"kw-def\">comorbidités</span> lourdes (probabilité de survie < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">10 ans</span></span>)</li></ul>"},{"id":"t-interm","kind":"terminal","label":"Options curatives — risque intermédiaire","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Prostatectomie totale + curage ganglionnaire</span> si espérance de vie > <span class=\"kw-chiffre\">10 ans</span></li><li><span class=\"kw-ttt\">Radiothérapie externe + hormonothérapie 6 mois</span></li><li><span class=\"kw-ttt\">Curiethérapie interstitielle</span> si <span class=\"kw-bio\">PSA 10-15 ng/mL</span> et <span class=\"kw-etio\">ISUP 2</span></li></ul>"},{"id":"t-haut","kind":"terminal","label":"Traitement multimodal — haut risque","color":"red","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Prostatectomie totale + curage</span> en association à d'autres traitements</li><li><span class=\"kw-ttt\">Radiothérapie externe + hormonothérapie ≥ 18 mois</span> (jusqu'à <span class=\"kw-chiffre\">36 mois</span>)</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-def\">Bilan d'extension</span> complet : <span class=\"kw-imagerie\">TDM thoraco-abdomino-pelvienne</span> + <span class=\"kw-imagerie\">tomoscintigraphie osseuse</span></li></ul>"}]},"cards":[{"i":"33e7910e5bdf","n":310,"o":"310-3","u":"Étiologie","t":"Connaître les principaux facteurs de risque du cancer de la prostate","q":"Quels sont les principaux facteurs génétiques impliqués dans le risque de cancer de la prostate ?","a":"<p>Le risque génétique est majoritairement polygénique (95%), mais des mutations constitutionnelles monogéniques sont documentées, notamment sur les gènes <strong>BRCA2</strong> (le plus important), BRCA1, HOXB13 et ATM. Ces formes héréditaires peuvent entraîner une survenue précoce et une agressivité accrue.</p>"},{"i":"4c228e89119f","n":310,"o":"310-3","u":"Étiologie","t":"Connaître les principaux facteurs de risque du cancer de la prostate","q":"Quel est l'impact de l'âge sur le risque de cancer de la prostate ?","a":"<p>L'âge est un <strong>facteur de risque majeur</strong> du cancer de la prostate. Le diagnostic est exceptionnel avant 50 ans, et le pic d'incidence se situe à <strong>68 ans</strong>.</p>"},{"i":"962e18878a8f","n":310,"o":"310-3","u":"Étiologie","t":"Connaître les principaux facteurs de risque du cancer de la prostate","q":"Quelle est l'influence de l'origine ethnique sur le risque de cancer de la prostate ?","a":"<p>Le risque de cancer de la prostate est hiérarchisé selon l'origine ethnique : les hommes à <strong>peau noire</strong> sont plus à risque que les caucasiens, qui sont eux-mêmes plus à risque que les asiatiques. Le <strong>surrisque est particulièrement marqué pour les ascendants d'Afrique noire et la population antillaise</strong>, qui présente une incidence, une mortalité et une agressivité accrues, avec plus de récidives.</p>"},{"i":"b12599e733b0","n":310,"o":"310-3","u":"Étiologie","t":"Connaître les principaux facteurs de risque du cancer de la prostate","q":"Quels sont les facteurs environnementaux et métaboliques associés au cancer de la prostate ?","a":"<ul><li>Le <strong>syndrome métabolique et l'obésité</strong> augmentent le risque de formes de cancer de la prostate à <strong>haut risque</strong>.</li><li>Les <strong>perturbateurs endocriniens</strong>, comme le <strong>chlordécone</strong> (insecticide utilisé aux Antilles), sont des facteurs de risque reconnus.</li><li>Une alimentation riche en graisses animales est parfois citée, mais avec un signal faible.</li></ul>"},{"i":"d42da400c523","n":310,"o":"310-3","u":"Étiologie","t":"Connaître les principaux facteurs de risque du cancer de la prostate","q":"Quels sont les éléments couramment évoqués mais qui ne sont PAS des facteurs de risque validés pour le cancer de la prostate ?","a":"<p>Ne sont <strong>PAS</strong> des facteurs de risque reconnus pour le cancer de la prostate : le <strong>tabac</strong>, l'<strong>alcool</strong>, le traitement androgénique, une faible fréquence éjaculatoire, et un régime alimentaire spécifique. Le tabac est un piège classique en QCM.</p>"},{"i":"1c2a227472b3","n":310,"o":"310-5","u":"Diagnostic positif","t":"Connaître les grandes présentations cliniques du cancer de la prostate","q":"Quelles sont les atteintes secondaires révélatrices d'un cancer de la prostate, pouvant être présentes au diagnostic ?","a":"<ul><li><strong>AEG/anémie</strong> par envahissement médullaire métastatique.</li><li><strong>Anurie</strong> par insuffisance rénale aiguë obstructive due à un envahissement des uretères.</li><li><strong>Douleurs osseuses inflammatoires</strong> (à prédominance nocturne) évocatrices de métastases osseuses.</li><li><strong>Signes neurologiques</strong> (paresthésies, déficit moteur, syndrome de la queue de cheval) par compression médullaire due à des métastases rachidiennes.</li><li><strong>Œdèmes des membres inférieurs asymétriques</strong>, indirectement liés à une compression veineuse par des adénopathies pelviennes.</li></ul>"},{"i":"58492604a595","n":310,"o":"310-5","u":"Diagnostic positif","t":"Connaître les grandes présentations cliniques du cancer de la prostate","q":"Quelle conduite tenir face à toute anomalie au toucher rectal évoquant un cancer de la prostate ?","a":"<p>Toute anomalie au toucher rectal (TR) évoquant un cancer impose la réalisation de <strong>biopsies prostatiques écho-guidées</strong>, et ce, <strong>indépendamment du taux de PSA</strong>.</p>"},{"i":"6c6c09edb605","n":310,"o":"310-5","u":"Diagnostic positif","t":"Connaître les grandes présentations cliniques du cancer de la prostate","q":"Quels sont les symptômes urinaires pouvant évoquer un cancer de la prostate, et quel en est le mécanisme principal ?","a":"<p>Les symptômes urinaires peuvent inclure des <strong>SBAU</strong> (signes du bas appareil urinaire), une <strong>hématurie</strong> ou une <strong>RAU</strong> (rétention aiguë d'urine). Le mécanisme est le plus souvent une <strong>HBP associée</strong>, et plus rarement un envahissement tumoral du trigone ou de l'urètre prostatique.</p>"},{"i":"6cf3fa8eef57","n":310,"o":"310-5","u":"Diagnostic positif","t":"Connaître les grandes présentations cliniques du cancer de la prostate","q":"Quelle est la présentation clinique la plus fréquente du cancer de la prostate ?","a":"<p>Le cancer de la prostate est le plus souvent <strong>asymptomatique</strong>, avec un diagnostic majoritairement réalisé suite à un <strong>dépistage individuel</strong> (Toucher Rectal + PSA).</p>"},{"i":"a685976051f3","n":310,"o":"310-5","u":"Diagnostic positif","t":"Connaître les grandes présentations cliniques du cancer de la prostate","q":"Quels sont les différentes présentations cliniques du cancer de la prostate à connaître ?","a":"<ul><li>La découverte d'un <strong>nodule suspect au toucher rectal</strong>.</li><li>Des <strong>symptômes urinaires</strong> (souvent liés à une HBP associée, plus rarement à un envahissement tumoral).</li><li>Des <strong>atteintes secondaires révélatrices</strong> (environ 10% des cas au diagnostic).</li></ul>"},{"i":"c10d68a28c32","n":310,"o":"310-5","u":"Diagnostic positif","t":"Connaître les grandes présentations cliniques du cancer de la prostate","q":"Comment différencier un nodule prostatique suspect de cancer d'une hypertrophie bénigne de la prostate (HBP) au toucher rectal ?","a":"<ul><li>Un cancer de la prostate se présente comme un <strong>nodule dur/pierreux</strong>, <strong>irrégulier</strong>, et <strong>non douloureux</strong> à la palpation.</li><li>Une HBP est caractérisée par une glande <strong>souple, lisse, indolore, régulière</strong>, avec un volume augmenté et la disparition du sillon médian.</li></ul>"},{"i":"6bcb764cf1a2","n":310,"o":"310-6","u":"Examens complémentaires","t":"Connaître les examens paracliniques de première intention devant une suspicion de cancer de la prostate (règles de bon usage du dosage de l’antigène prostatique spécifique (PSA))","q":"Quelle est la place de l'IRM prostatique multiparamétrique (IRMmp) dans l'arbre décisionnel du diagnostic du cancer de la prostate ?","a":"<p>L'<strong>IRMmp n'est pas recommandée avant la décision de biopsie</strong>. Son indication vient <strong>APRÈS la décision de biopsie</strong>, pour préparer le geste en permettant un guidage précis des prélèvements. Elle ne doit pas être utilisée pour poser l'indication de biopsie.</p>"},{"i":"740fafafae98","n":310,"o":"310-6","u":"Examens complémentaires","t":"Connaître les examens paracliniques de première intention devant une suspicion de cancer de la prostate (règles de bon usage du dosage de l’antigène prostatique spécifique (PSA))","q":"Quelle est la définition et la spécificité de l'Antigène Prostatique Spécifique (PSA) ?","a":"<p>Le PSA est une <strong>glycoprotéine de la famille des kallikréines</strong>. Son rôle est la liquéfaction du sperme. Il est <strong>spécifique de l'épithélium prostatique</strong> (sain ou tumoral), mais <strong>n'est pas spécifique du cancer de la prostate</strong>.</p>"},{"i":"cb9ac7ebeb8f","n":310,"o":"310-6","u":"Examens complémentaires","t":"Connaître les examens paracliniques de première intention devant une suspicion de cancer de la prostate (règles de bon usage du dosage de l’antigène prostatique spécifique (PSA))","q":"Comment interpréter les variations du taux de PSA et quels facteurs peuvent l'influencer en dehors du cancer de la prostate ?","a":"<ul><li>Une augmentation du PSA peut être causée par le <strong>cancer de la prostate</strong>, l'<strong>hypertrophie bénigne de la prostate (HBP)</strong>, une <strong>prostatite aiguë</strong>, une <strong>rétention aiguë d'urine (RAU)</strong> ou des <strong>manipulations prostatiques</strong> (toucher rectal, sondage).</li><li>Une diminution du PSA peut être observée sous <strong>inhibiteurs de la 5α-réductase</strong> (jusqu'à -50%), ou après certains <strong>traitements anticancéreux</strong> (PSA < 0,2 ng/mL ou indosable après prostatectomie totale).</li></ul>"},{"i":"de93c556c4b9","n":310,"o":"310-6","u":"Examens complémentaires","t":"Connaître les examens paracliniques de première intention devant une suspicion de cancer de la prostate (règles de bon usage du dosage de l’antigène prostatique spécifique (PSA))","q":"Quelles sont les règles de bon usage du PSA lors d'une suspicion de cancer de la prostate ?","a":"<ul><li>Il faut toujours <strong>confirmer un PSA élevé par un deuxième dosage à un mois</strong> (variabilité intra-individuelle de 20-30%) avant d'adresser le patient en urologie.</li><li>Il faut <strong>éviter le dosage en cas d'événement perturbateur récent</strong> (infection urinaire masculine, toucher rectal récent, sondage, RAU, prostatite) et le répéter à distance.</li><li>La <strong>densité du PSA</strong> (PSA / volume prostatique) peut être un argument supplémentaire pour des biopsies prostatiques si elle est <strong>supérieure à 0,15</strong>.</li></ul>"}]};